result = Customers.WHERE(
    COUNT(transactions_made) >= 5
).CALCULATE(
    customer_name=name,
    success_rate=100.0 * COUNT(transactions_made.WHERE(LOWER(status) == LOWER('success'))) / COUNT(transactions_made)
).ORDER_BY(success_rate.ASC())

result = Broker.CALCULATE(
    num_customers = COUNT(
        Customers.WHERE(
            ENDSWITH(email, '.com') & 
            HAS(
                transactions_made.WHERE(
                    CONTAINS(ticker.symbol, 'AMZN') |
                    CONTAINS(ticker.symbol, 'AAPL') |
                    CONTAINS(ticker.symbol, 'GOOGL') |
                    CONTAINS(ticker.symbol, 'META') |
                    CONTAINS(ticker.symbol, 'NFLX')
                )
            ) == 1
        )
    )
)

result = Customers.WHERE(
    (join_date >= "2023-01-01") & 
    (LOWER(status) == "active")
).PARTITION(
    name="countries", 
    by=country
).CALCULATE(
    country=country,
    count=COUNT(Customers)
)

tac_by_country = Customers.WHERE(
    (LOWER(status) == 'active') & (join_date >= '2023-01-01')
).PARTITION(
    name='country_groups', by=(country)
).CALCULATE(
    country=country,
    tac_count=COUNT(Customers)
)

top_bought_tickers = Transactions.WHERE(
    (DATEDIFF("days", date_time, DATETIME('now')) <= 10) & (LOWER(transaction_type) == 'buy')
).CALCULATE(
    ticker_symbol=ticker.symbol
).PARTITION(
    name="ticker_groups", by=(ticker_symbol)
).CALCULATE(
    ticker_symbol=ticker_symbol,
    num_buy_transactions=COUNT(Transactions)
).TOP_K(2, by=num_buy_transactions.DESC())

recent_customers_by_month = Customers.WHERE(
    (DATEDIFF("months", join_date, DATETIME('now')) > 0) & (DATEDIFF("months", join_date, DATETIME('now')) <= 6)
).CALCULATE(
    signup_month=JOIN_STRINGS("-", YEAR(join_date), LPAD(MONTH(join_date), 2, "0"))
)

result = recent_customers_by_month.PARTITION(name="monthly_groups", by=(signup_month)).CALCULATE(
    month=signup_month,
    PMCS=COUNT(Customers),
    PMAT=AVG(Customers.transactions_made.amount)
).ORDER_BY(signup_month.ASC())

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Broker.CALCULATE(
    num_customers=COUNT(
        Customers.WHERE(
            (STARTSWITH(LOWER(name), 'j') | ENDSWITH(LOWER(name), 'ez')) &
            ENDSWITH(LOWER(state), 'a')
        )
    )
)

result = Customers.WHERE(
    HAS(transactions_made.WHERE(LOWER(transaction_type) == LOWER('buy'))) == 1
).CALCULATE(
    customer_id=_id
)

result = DailyPrices.WHERE(
    date >= "2023-04-01"
).PARTITION(name="tickers", by=ticker_id).CALCULATE(
    ticker_id=ticker_id
)

distinct_ticker_ids = DailyPrices.WHERE(
    date >= '2023-04-01'
).PARTITION(
    name="unique_tickers", by=ticker_id
).CALCULATE(
    ticker_id
)

result = Tickers.WHERE(
    HASNOT(historical_prices) == 1
).CALCULATE(
    ticker_id=_id,
    symbol=symbol
)

result = Transactions.WHERE(
    DATEDIFF("days", date_time, 'now') <= 30
).CALCULATE(
    country_name=customer.country
).PARTITION(
    name="countries", by=(country_name)
).CALCULATE(
    country=country_name,
    num_transactions=COUNT(Transactions),
    total_transaction_amount=SUM(Transactions.amount)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Broker.CALCULATE(
    lowest_close_price=MIN(
        DailyPrices.WHERE(
            (ticker.symbol == 'VTI') & 
            (DATEDIFF("days", date, DATETIME('now')) <= 7)
        ).close
    )
)

vti_prices_in_range = DailyPrices.WHERE(
    (LOWER(ticker.symbol) == 'vti') & (DATEDIFF("days", date, 'now') <= 7)
)
result = GRAPH.CALCULATE(
    lowest_daily_close_price=MIN(vti_prices_in_range.close)
)

result = Broker.CALCULATE(
    num_transactions=COUNT(
        Customers.WHERE(
            DATEDIFF("days", join_date, DATETIME("now")) <= 70
        ).transactions_made
    )
)

result = Customers.WHERE(
    HAS(transactions_made) == 1
).CALCULATE(
    customer_id=_id,
    days_to_first_transaction=DATEDIFF("seconds", join_date, MIN(transactions_made.date_time)) / 86400
)

result = Customers.CALCULATE(
    customer_id=_id,
    customer_name=name,
    num_sell_transactions=COUNT(
        transactions_made.WHERE(
            (DATE(date_time) == "2023-04-01") & 
            (LOWER(transaction_type) == "sell")
        )
    )
).TOP_K(1, by=num_sell_transactions.DESC())

sales_by_model_with_m5_vin = Dealership.Cars.WHERE(
    LIKE(LOWER(vin_number), '%m5%')
).PARTITION(
    name="car_models", by=(make, model)
).CALCULATE(
    make=make,
    model=model,
    number_of_sales=COUNT(Cars.sale_records)
)

toyota_sales_last_30_days = Cars.WHERE(
    LOWER(make) == LOWER('Toyota')
).sale_records.WHERE(
    DATEDIFF("days", sale_date, DATETIME('now')) <= 30
)

result = Dealership.CALCULATE(
    number_of_sales=COUNT(toyota_sales_last_30_days),
    total_revenue=SUM(toyota_sales_last_30_days.sale_price)
)

result = Sales.WHERE(
    (YEAR(sale_date) == 2023) & 
    (ISIN(MONTH(sale_date), (1, 2, 3)))
).CALCULATE(
    asp_q1_2023 = AVG(Sales.sale_price)
)

result = Dealership.CALCULATE(
    avg_days_to_payment=ROUND(
        AVG(
            Sales.WHERE(HAS(payment) == 1).payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_record.sale_date, payment_date)
            ).days_diff
        ), 
        2
    )
)

avg_payment_days_per_sale = Sales.WHERE(HAS(payment) == 1).CALCULATE(
    sale_id=_id,
    avg_days_to_payment=ROUND(
        AVG(
            payment.CALCULATE(
                days_diff=DATEDIFF("days", sale_date, payment_date)
            ).days_diff
        ),
        2
    )
)

highest_priced_car = Sales.WHERE(
    HAS(car.inventory_snapshots.WHERE((snapshot_date == sale_date) & (is_in_inventory == False))) == 1
).TOP_K(
    1, by=sale_price.DESC()
).CALCULATE(
    make=car.make,
    model=car.model,
    sale_price=sale_price
)

result = Customers.WHERE(
    HAS(car_purchases) == 1
).CALCULATE(
    customer_id=_id
)

distinct_customer_ids = Sales.PARTITION(name="customers_with_sales", by=(customer_id)).CALCULATE(
    customer_id=customer_id
)

result = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == LOWER("cash"))) == 1
).CALCULATE(
    salesperson_id=_id
)

cash_salesperson_ids = Salespersons.WHERE(
    HAS(sales_made.payment.WHERE(LOWER(payment_method) == 'cash')) == 1
).CALCULATE(
    salesperson_id=_id
)

result = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == LOWER('Utility Company')) &
            (ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday')))
        )
    )
)

weekend_payments_to_utility_co = Dealership.CALCULATE(
    num_weekend_payments=COUNT(
        PaymentsMade.WHERE(
            (LOWER(vendor_name) == 'utility company') & 
            ISIN(DAYNAME(payment_date), ('Saturday', 'Sunday'))
        )
    )
)

result = Drugs.CALCULATE(
    drug_name=drug_name,
    avg_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt)
        ).CALCULATE(
            ddd=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd
    )
)

result = DermTreatment.Drugs.CALCULATE(
    drug_name=drug_name,
    average_ddd=AVG(
        treatments_used_in.WHERE(
            PRESENT(end_dt) & (DATEDIFF("days", start_dt, end_dt) > 0)
        ).CALCULATE(
            ddd_value=tot_drug_amt / DATEDIFF("days", start_dt, end_dt)
        ).ddd_value
    )
)

result = DermTreatment.CALCULATE(
    num_patients_gmail_yahoo = COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), "@gmail.com") | ENDSWITH(LOWER(email), "@yahoo.com")
        )
    )
)

gmail_or_yahoo_patients_count = DermTreatment.CALCULATE(
    num_patients=COUNT(
        Patients.WHERE(
            ENDSWITH(LOWER(email), '@gmail.com') | ENDSWITH(LOWER(email), '@yahoo.com')
        )
    )
)

result = DermTreatment.CALCULATE(
    patient_count=COUNT(
        Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == LOWER('Psoriasis vulgaris')) &
                    (LOWER(drug.drug_type) == LOWER('Biologic'))
                )
            ) == 1
        )
    )
)

result = DermTreatment.CALCULATE(
    num_patients=COUNT(
        DermTreatment.Patients.WHERE(
            HAS(
                treatments_received.WHERE(
                    (LOWER(diagnosis.diag_name) == 'psoriasis vulgaris') & 
                    (LOWER(drug.drug_type) == 'biologic')
                )
            ) == 1
        )
    )
)

# Calculate the date range: from 6 months ago to the start of current month
result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(
            LOWER(first_name) == LOWER('Alice')
        ).treatments_received.WHERE(
            (start_dt >= DATETIME('now', 'start of month', '-6 months')) &
            (start_dt < DATETIME('now', 'start of month'))
        )
    )
)

alice_treatments_in_last_6_months = DermTreatment.CALCULATE(
    start_of_current_month=DATETIME('now', 'start of month'),
    six_months_ago=DATETIME('now', 'start of month', '-6 months')
).CALCULATE(
    num_treatments=COUNT(
        Patients.WHERE(LOWER(first_name) == 'alice').treatments_received.WHERE(
            (start_dt >= six_months_ago) & (start_dt < start_of_current_month)
        )
    )
)

result = Drugs.WHERE(
    LOWER(drug_name) == LOWER('Drugalin')
).CALCULATE(
    avg_weight=AVG(treatments_used_in.patient.weight_kg)
)

result = DermTreatment.CALCULATE(
    avg_patient_weight=AVG(Patients.WHERE(HAS(treatments_received.WHERE(LOWER(drug.drug_name) == 'drugalin')) == 1).weight_kg)
)

result = Patients.WHERE(LOWER(gender) == 'male').CALCULATE(
    caw=AVG(Patients.weight_kg)
)

caw_for_male_patients = DermTreatment.CALCULATE(
    caw=AVG(Patients.WHERE(LOWER(gender) == 'male').weight_kg)
)

new_patients_by_year = DermTreatment.Patients.WHERE(
    HAS(treatments_received) == 1
).CALCULATE(
    first_treatment_year=YEAR(MIN(treatments_received.start_dt))
).PARTITION(
    name="yearly_groups", by=first_treatment_year
).CALCULATE(
    year=first_treatment_year,
    num_new_patients=COUNT(Patients)
).ORDER_BY(
    year.ASC()
).CALCULATE(
    year=year,
    number_of_new_patients=num_new_patients,
    NPINPI=num_new_patients - PREV(num_new_patients, by=year.ASC())
)

overall_d7d100pir = DermTreatment.CALCULATE(
    avg_pasi_d7=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day7_pasi_score),
    avg_pasi_d100=AVG(Outcomes.WHERE(PRESENT(day7_pasi_score) & PRESENT(day100_pasi_score)).day100_pasi_score)
).CALCULATE(
    d7d100pir=(avg_pasi_d100 - avg_pasi_d7) / avg_pasi_d7 * 100.0
)

result = DermTreatment.CALCULATE(
    pic_female = COUNT(Patients.WHERE(
        (LOWER(gender) == 'female') & 
        (LOWER(ins_type) == 'private')
    ))
)

result = DermTreatment.CALCULATE(
    PIC=COUNT(Patients.WHERE((LOWER(gender) == 'female') & (LOWER(ins_type) == 'private')))
)

result = Drugs.CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name,
    num_adverse_events=COUNT(
        treatments_used_in.adverse_events.WHERE(
            (YEAR(reported_dt) == YEAR(treatment.start_dt)) & (MONTH(reported_dt) == MONTH(treatment.start_dt))
        )
    )
).TOP_K(1, by=num_adverse_events.DESC())

# Find doctors who have prescribed biologic drugs and get their distinct states
result = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == LOWER("Biologic"))) == 1
).PARTITION(name="states", by=(loc_state,)).CALCULATE(
    state=loc_state
)

doctor_states_for_biologics = Doctors.WHERE(
    HAS(prescribed_treatments.WHERE(LOWER(drug.drug_type) == 'biologic')) == 1
).PARTITION(
    name="states", by=loc_state
).CALCULATE(
    state=loc_state
)

result = Drugs.WHERE(
    HASNOT(treatments_used_in) == 1
).CALCULATE(
    drug_id=drug_id,
    drug_name=drug_name
)

top_diagnoses = Diagnoses.WHERE(
    HAS(treatments_for.outcome_records) == 1
).CALCULATE(
    diag_name=diag_name,
    num_patients=NDISTINCT(treatments_for.patient.patient_id),
    max_itch_score=MAX(treatments_for.outcome_records.day100_itch_vas)
).TOP_K(
    3,
    by=(max_itch_score.DESC(), num_patients.DESC())
)

result = DermTreatment.CALCULATE(
    num_treatments=COUNT(
        Treatments.WHERE(
            CONTAINS(LOWER(diagnosis.diag_name), "psoriasis") &
            (drug.fda_appr_dt != None) &
            (DATEDIFF("days", end_dt, DATETIME("now")) <= 180)
        )
    )
)

recent_psoriasis_treatments = DermTreatment.CALCULATE(
    treatment_count=COUNT(
        Treatments.WHERE(
            (LIKE(LOWER(diagnosis.diag_name), '%psoriasis%')) &
            (PRESENT(drug.fda_appr_dt)) &
            (PRESENT(end_dt)) &
            (DATEDIFF("months", end_dt, DATETIME('now')) <= 6)
        )
    )
)

# Get doctors registered 2 years ago and their first treatment
result = Doctors.WHERE(
    year_reg == YEAR(DATETIME('now', '-2 years'))
).CALCULATE(
    doctor_last_name=last_name,
    registration_year=year_reg,
    first_treatment_date=prescribed_treatments.WHERE(
        RANKING(by=start_dt.ASC(), per="Doctors") == 1
    ).SINGULAR().start_dt,
    first_treatment_id=prescribed_treatments.WHERE(
        RANKING(by=start_dt.ASC(), per="Doctors") == 1
    ).SINGULAR().treatment_id
)

doctors_first_treatment = DermTreatment.Doctors.WHERE(
    year_reg == (YEAR(DATETIME('now')) - 2)
).prescribed_treatments.WHERE(
    RANKING(by=start_dt.ASC(), per="Doctors") == 1
).CALCULATE(
    doctor_last_name=last_name,
    registration_year=year_reg,
    first_treatment_id=treatment_id,
    first_treatment_date=start_dt
)

result = Treatments.WHERE(
    HAS(adverse_events) == 1
).adverse_events.WHERE(
    DATEDIFF("days", treatment.start_dt, reported_dt) <= 10
).CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_date=treatment.start_dt,
    adverse_event_date=reported_dt,
    adverse_event_description=description
)

result = Treatments.WHERE(
    is_placebo == True
).WHERE(
    HAS(concomitant_meds.WHERE(
        DATEDIFF("days", start_dt, concomitant_meds.start_dt) <= 14
    )) == 1
).concomitant_meds.CALCULATE(
    treatment_id=treatment.treatment_id,
    treatment_start_dt=treatment.start_dt,
    treatment_end_dt=treatment.end_dt,
    concomitant_med_start_dt=start_dt,
    concomitant_med_end_dt=end_dt
)

result = Patients.WHERE(
    (LOWER(gender) == LOWER('male')) & 
    (LOWER(ins_type) == LOWER('private'))
).CALCULATE(
    age_in_years = DATEDIFF("years", date_of_birth, DATETIME('now'))
).CALCULATE(
    average_age = AVG(age_in_years)
)

# First, create a collection of male patients with private insurance and calculate their current age in years.
male_private_patients_with_age = DermTreatment.Patients.WHERE(
    (LOWER(gender) == 'male') & (LOWER(ins_type) == 'private')
).CALCULATE(
    age=DATEDIFF("years", date_of_birth, 'now')
)

# Next, calculate the average of the ages from the collection above and round it to the nearest integer.
result = DermTreatment.CALCULATE(
    avg_patient_age=ROUND(AVG(male_private_patients_with_age.age), 0)
)

result = Users.WHERE(LOWER(country) == LOWER('US')).transactions_sent.WHERE(
    DATEDIFF("days", created_at, DATETIME('now')) <= 7
).CALCULATE(
    num_transactions=COUNT(Transactions),
    total_amount=SUM(amount)
).SINGULAR()

result = Users.CALCULATE(
    user_id=uid,
    marketing_opt_in=setting_snapshots.WHERE(
        RANKING(by=snapshot_date.DESC(), per="Users") == 1
    ).SINGULAR().marketing_opt_in
)

result = Users.WHERE(
    LOWER(user_type) != LOWER('merchant')
).CALCULATE(
    user_id=uid,
    total_transactions_sent=COUNT(transactions_sent)
)

result = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= "2023-06-01") & 
            (session_start_ts < "2023-06-08")
        ).CALCULATE(
            duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_seconds
    )
).WHERE(
    HAS(sessions.WHERE(
        (session_start_ts >= "2023-06-01") & 
        (session_start_ts < "2023-06-08")
    )) == 1
).ORDER_BY(total_duration.DESC())

user_session_duration = Users.CALCULATE(
    user_id=uid,
    total_duration=SUM(
        sessions.WHERE(
            (session_start_ts >= '2023-06-01') & (session_start_ts < '2023-06-08')
        ).CALCULATE(
            duration_in_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
        ).duration_in_seconds
    )
).ORDER_BY(total_duration.DESC())

result = Ewallet.CALCULATE(
    total_count=COUNT(UserSessions.WHERE(
        DATEDIFF("days", session_start_ts, DATETIME('now')) <= 30
    ))
)

tuc_result = Ewallet.CALCULATE(
    tuc_count=COUNT(UserSessions.WHERE(session_start_ts >= DATETIME('now', '-1 month')))
)

result = Transactions.WHERE(
    receiver_type == 1
).CALCULATE(
    merchant_id=receiver_id
).PARTITION(
    name="merchants", 
    by=merchant_id
).CALCULATE(
    merchant_id=merchant_id
)

result = Users.WHERE(
    HAS(notifications.WHERE(CONTAINS(LOWER(notification_type), "transaction"))) == 1
).CALCULATE(
    user_id=uid
)

distinct_user_ids_with_transaction_notifications = Notifications.WHERE(
    LOWER(notification_type) == 'transaction'
).PARTITION(
    name="users_with_transaction_notifications", by=user_id
).CALCULATE(
    user_id
)

top_5_countries_by_sent_amount = Ewallet.Transactions.WHERE(
    sender_type == 0
).CALCULATE(
    sender_country=sending_user.country,
    tx_amount=amount,
    sender_uid=sending_user.uid
).PARTITION(
    name="countries", by=(sender_country)
).CALCULATE(
    country=sender_country,
    total_transaction_amount=SUM(Transactions.tx_amount),
    num_distinct_users=NDISTINCT(Transactions.sender_uid)
).TOP_K(5, by=total_transaction_amount.DESC())

result = Merchants.WHERE(
    HAS(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )) == 1
).CALCULATE(
    merchant_name=name,
    total_transactions=COUNT(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    )),
    total_amount=SUM(transactions_received.WHERE(
        (receiver_type == 1) & 
        (DATEDIFF("days", created_at, DATETIME("now")) <= 150)
    ).amount)
).TOP_K(2, by=total_amount.DESC())

result = Ewallet.CALCULATE(
    median_merchant_balance=MEDIAN(
        Merchants.WHERE(
            (LOWER(status) == 'active') & 
            (CONTAINS(LOWER(category), 'retail'))
        ).balances.WHERE(
            updated_at >= DATETIME('now', 'start of day')
        ).balance
    )
)

# First, find the earliest snapshot date in 2023
earliest_date_2023 = UserSettingSnapshots.WHERE(
    YEAR(snapshot_date) == 2023
).CALCULATE(
    min_date=MIN(UserSettingSnapshots.snapshot_date)
).SINGULAR().min_date

# Then calculate the averages for that specific date
result = Ewallet.CALCULATE(
    avg_daily_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_daily
    ),
    avg_monthly_limit=AVG(
        UserSettingSnapshots.WHERE(
            snapshot_date == earliest_date_2023
        ).tx_limit_monthly
    )
)

session_duration_by_device = Ewallet.UserSessions.CALCULATE(
    session_duration_seconds=DATEDIFF("seconds", session_start_ts, session_end_ts)
).PARTITION(
    name="sessions_by_device", 
    by=(device_type)
).CALCULATE(
    device_type=device_type,
    average_duration_in_seconds=AVG(UserSessions.session_duration_seconds)
)

merchants_with_early_coupons = Ewallet.Merchants.WHERE(
    HAS(coupons) == 1
).CALCULATE(
    earliest_coupon_info=coupons.TOP_K(1, by=start_date.ASC()).SINGULAR()
).CALCULATE(
    merchant_id=mid,
    registration_date=created_at,
    earliest_coupon_id=earliest_coupon_info.cid,
    earliest_coupon_start_date=earliest_coupon_info.start_date
).WHERE(
    DATEDIFF("days", registration_date, earliest_coupon_start_date) <= 365
)

result = Users.WHERE(
    HASNOT(notifications.WHERE(
        (created_at >= Users.created_at) & 
        (created_at <= DATETIME(Users.created_at, '+1 year'))
    )) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)

users_without_notifications_in_first_year = Ewallet.Users.WHERE(
    HASNOT(
        notifications.WHERE(created_at < DATETIME(created_at, '+1 year'))
    ) == 1
).CALCULATE(
    username=username,
    email=email,
    signup_date=created_at
)
